// sunny-mwi-legacy-market-sort: restore the 1.1.35 My Listings toolbar
(() => {
  "use strict";

  const PANEL_SEL = '[class*="MarketplacePanel_myListings__"]:not([class*="myListingsTable"])';
  const TABLE_SEL = 'table[class*="MarketplacePanel_myListingsTable__"]';
  const BUTTONS_SEL = '[class*="MarketplacePanel_buttonContainer__"]';
  const MODAL_SEL = '[class*="MarketplacePanel_modalContent__"], [class*="Modal_modalContainer__"]';
  const ROOT_CLASS = "sunnyMwi-legacy-market-sort";
  const STYLE_ID = "sunnyMwi-legacy-market-sort-style";
  const STORAGE_KEY = "sunnyMwi_legacy_market_sort_state";
  const SORT_MODES = [
    { key: "time-asc", label: "时间↑" },
    { key: "time-desc", label: "时间↓" },
    { key: "name-asc", label: "名称↑" },
    { key: "name-desc", label: "名称↓" },
    { key: "price-asc", label: "价格↑" },
    { key: "price-desc", label: "价格↓" },
  ];

  let state = loadState();
  let activeSurface = null;
  let bodyObserver = null;
  let tableObserver = null;
  let observedTbody = null;
  let collectListenerTbody = null;
  let sortTimer = null;
  let mountTimer = null;
  let sortInProgress = false;
  let suppressMutationsUntil = 0;
  let rowTimestamps = new WeakMap();

  function loadState() {
    const fallback = { sortKey: "time-asc", pinCollectable: true };
    try {
      const get = typeof GM_getValue === "function" ? GM_getValue : null;
      const value = get ? get(STORAGE_KEY, null) : JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
      if (!value || typeof value !== "object") return fallback;
      const sortKey = SORT_MODES.some((mode) => mode.key === value.sortKey) ? value.sortKey : fallback.sortKey;
      return { sortKey, pinCollectable: typeof value.pinCollectable === "boolean" ? value.pinCollectable : true };
    } catch (_) {
      return fallback;
    }
  }

  function saveState() {
    try {
      if (typeof GM_setValue === "function") GM_setValue(STORAGE_KEY, state);
      else localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (_) { /* storage is optional */ }
  }

  function currentSortIndex() {
    const index = SORT_MODES.findIndex((mode) => mode.key === state.sortKey);
    return index >= 0 ? index : 0;
  }

  function isHidden(element) {
    if (!element || !element.isConnected) return true;
    if (element.closest(MODAL_SEL)) return true;
    if (element.hidden || element.getAttribute("aria-hidden") === "true") return true;
    try {
      const style = getComputedStyle(element);
      return style.display === "none" || style.visibility === "hidden" || style.visibility === "collapse";
    } catch (_) {
      return false;
    }
  }

  function findSurface() {
    for (const panel of Array.from(document.querySelectorAll(PANEL_SEL))) {
      if (isHidden(panel)) continue;
      const table = panel.querySelector(TABLE_SEL);
      const buttonContainer = panel.querySelector(BUTTONS_SEL);
      const tbody = table?.querySelector("tbody");
      if (table && buttonContainer && tbody) return { panel, table, buttonContainer, tbody };
    }
    return null;
  }

  function getRows(tbody) {
    return tbody ? Array.from(tbody.children).filter((row) => row.tagName === "TR" && row.querySelector("td")) : [];
  }

  function itemName(row) {
    try {
      const svg = row.querySelector('svg[aria-label]');
      if (svg) return svg.getAttribute("aria-label") || "";
      return row.querySelector('[class*="Item_item__"]')?.textContent?.trim() || "";
    } catch (_) {
      return "";
    }
  }

  function priceValue(row) {
    try {
      const text = (row.querySelector('[class*="MarketplacePanel_price__"] span')?.textContent || "")
        .replace(/,/g, "").replace(/[^0-9.KMB]/gi, "");
      const value = Number.parseFloat(text);
      if (!Number.isFinite(value)) return 0;
      if (/B/i.test(text)) return value * 1e9;
      if (/M/i.test(text)) return value * 1e6;
      if (/K/i.test(text)) return value * 1e3;
      return value;
    } catch (_) {
      return 0;
    }
  }

  function isCollectable(row) {
    try {
      const claims = row.querySelector('[class*="MarketplacePanel_claimsContainer__"]');
      const button = claims?.querySelector("button");
      return !!button && /收集|Claim/i.test(button.textContent || "");
    } catch (_) {
      return false;
    }
  }

  function seedRowTimestamps(tbody, reset) {
    if (reset) rowTimestamps = new WeakMap();
    const now = Date.now();
    getRows(tbody).forEach((row, index) => {
      if (!rowTimestamps.has(row)) rowTimestamps.set(row, now + index);
    });
  }

  function sortRows() {
    const surface = activeSurface || findSurface();
    const tbody = surface?.tbody;
    if (!tbody || sortInProgress) return;
    seedRowTimestamps(tbody, false);
    const rows = getRows(tbody);
    if (rows.length < 2) return;
    sortInProgress = true;
    suppressMutationsUntil = Date.now() + 250;
    try {
      const mode = SORT_MODES[currentSortIndex()];
      const descending = mode.key.endsWith("-desc");
      const field = mode.key.replace(/-(?:asc|desc)$/, "");
      const data = rows.map((row, index) => ({
        row, index, name: itemName(row), price: priceValue(row),
        time: rowTimestamps.get(row) || Date.now(), collectable: isCollectable(row),
      }));
      data.sort((left, right) => {
        if (state.pinCollectable && left.collectable !== right.collectable) return left.collectable ? -1 : 1;
        let result = 0;
        if (field === "name") result = left.name.localeCompare(right.name, "zh-CN");
        else if (field === "price") result = left.price - right.price;
        else result = left.time - right.time;
        return (result || left.index - right.index) * (descending ? -1 : 1);
      });
      const fragment = document.createDocumentFragment();
      data.forEach(({ row, collectable }) => {
        row.style.backgroundColor = collectable ? "rgba(76,175,80,0.15)" : "";
        fragment.appendChild(row);
      });
      tbody.appendChild(fragment);
    } catch (_) {
      // React may replace the table during a render; the next observer pass retries.
    } finally {
      sortInProgress = false;
    }
  }

  function scheduleSort(delay = 0) {
    if (sortTimer) clearTimeout(sortTimer);
    sortTimer = setTimeout(() => { sortTimer = null; sortRows(); }, delay);
  }

  function buttonStyle(button, color, minWidth) {
    button.style.cssText = [
      `background-color:${color}`, "color:white", "border:none", "font-size:12px", "padding:3px 8px",
      `min-width:${minWidth}px`,
    ].join(";");
  }

  function mountControls(surface) {
    const { buttonContainer, tbody } = surface;
    buttonContainer.querySelectorAll(`.${ROOT_CLASS}`).forEach((node) => node.remove());
    if (!document.getElementById(STYLE_ID)) {
      const style = document.createElement("style");
      style.id = STYLE_ID;
      style.textContent = [
        `[class*="MarketplacePanel_myListings__"] [class*="MarketplacePanel_buttonContainer__"]{display:flex!important;align-items:center!important;gap:10px!important;flex-wrap:wrap!important}`,
        `[class*="MarketplacePanel_myListings__"] [class*="MarketplacePanel_listingCount__"]{margin-right:auto!important}`,
        `.${ROOT_CLASS}{order:-1!important;display:flex!important;align-items:center!important;gap:6px!important}`,
      ].join("");
      (document.head || document.documentElement).appendChild(style);
    }

    const group = document.createElement("div");
    group.className = ROOT_CLASS;
    group.title = "Sunny 1.1.35 挂单排序增强";

    const refreshButton = document.createElement("button");
    refreshButton.type = "button";
    refreshButton.className = "Button_button__1Fe9z Button_small__3fqC7";
    refreshButton.textContent = "刷新";
    refreshButton.title = "重置挂单时间顺序并重新排序";
    buttonStyle(refreshButton, "#4CAF50", 48);
    refreshButton.addEventListener("click", (event) => {
      event.preventDefault(); event.stopPropagation();
      refreshButton.disabled = true;
      const original = refreshButton.textContent;
      refreshButton.textContent = "刷新中...";
      setTimeout(() => {
        try { seedRowTimestamps(tbody, true); sortRows(); }
        finally { refreshButton.disabled = false; refreshButton.textContent = original; }
      }, 120);
    });

    const pinLabel = document.createElement("span");
    pinLabel.textContent = "置顶:";
    pinLabel.style.cssText = "display:inline-flex;align-items:center;font-size:12px;color:var(--color-text-dark-mode,#eee);padding:0 2px;";

    const pinButton = document.createElement("button");
    pinButton.type = "button";
    pinButton.className = "Button_button__1Fe9z Button_small__3fqC7";
    pinButton.title = "可收取挂单行强制置顶";
    const updatePinButton = () => {
      pinButton.textContent = "可收取";
      buttonStyle(pinButton, state.pinCollectable ? "#4CAF50" : "#555", 56);
      if (!state.pinCollectable) pinButton.style.opacity = "0.85";
    };
    updatePinButton();
    pinButton.addEventListener("click", (event) => {
      event.preventDefault(); event.stopPropagation();
      state.pinCollectable = !state.pinCollectable;
      saveState(); updatePinButton(); scheduleSort();
    });

    const sortButton = document.createElement("button");
    sortButton.type = "button";
    sortButton.className = "Button_button__1Fe9z Button_small__3fqC7";
    sortButton.title = "循环切换：时间↑ → 时间↓ → 名称↑ → 名称↓ → 价格↑ → 价格↓";
    const updateSortButton = () => {
      sortButton.textContent = `排序 (${SORT_MODES[currentSortIndex()].label})`;
      buttonStyle(sortButton, "#2196F3", 92);
    };
    updateSortButton();
    sortButton.addEventListener("click", (event) => {
      event.preventDefault(); event.stopPropagation();
      state.sortKey = SORT_MODES[(currentSortIndex() + 1) % SORT_MODES.length].key;
      saveState(); updateSortButton(); scheduleSort();
    });

    group.append(refreshButton, pinLabel, pinButton, sortButton);
    buttonContainer.insertBefore(group, buttonContainer.firstChild);
    seedRowTimestamps(tbody, false);
  }

  function onCollectClick(event) {
    const button = event.target?.closest?.("button");
    if (!button || !/收集|Claim/i.test(button.textContent || "")) return;
    scheduleSort(450); setTimeout(() => scheduleSort(0), 900);
  }

  function observeSurface(surface) {
    if (observedTbody === surface.tbody) return;
    if (tableObserver) tableObserver.disconnect();
    if (collectListenerTbody) collectListenerTbody.removeEventListener("click", onCollectClick, true);
    observedTbody = surface.tbody;
    collectListenerTbody = observedTbody;
    collectListenerTbody.addEventListener("click", onCollectClick, true);
    tableObserver = new MutationObserver(() => {
      if (Date.now() < suppressMutationsUntil) return;
      seedRowTimestamps(observedTbody, false); scheduleSort(80);
    });
    tableObserver.observe(observedTbody, { childList: true, subtree: true });
  }

  function mount() {
    const surface = findSurface();
    if (!surface) return;
    const sameSurface = activeSurface && activeSurface.tbody === surface.tbody && activeSurface.buttonContainer === surface.buttonContainer;
    activeSurface = surface;
    const hasControls = !!surface.buttonContainer.querySelector(`.${ROOT_CLASS}`);
    if (!hasControls) mountControls(surface);
    observeSurface(surface);
    if (!sameSurface || !hasControls) scheduleSort(0);
  }

  function scheduleMount(delay = 0) {
    if (mountTimer) clearTimeout(mountTimer);
    mountTimer = setTimeout(() => { mountTimer = null; mount(); }, delay);
  }

  function start() {
    if (!document.body || bodyObserver) return;
    bodyObserver = new MutationObserver(() => scheduleMount(50));
    bodyObserver.observe(document.body, { childList: true, subtree: true });
    scheduleMount(0);
  }

  try {
    window.__SUNNY_MWI_LEGACY_MARKET_SORT__ = Object.freeze({
      version: "1.1.35-compat", state: () => ({ ...state }), remount: () => scheduleMount(0),
    });
  } catch (_) { /* diagnostics are optional */ }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start, { once: true });
  else start();
})();
